#include <iostream.h>
#include <conio.h>
class CRectangle
{
private:
int X, Y;
public:
void set_values (int a,int b)
{
X=a;
Y=b;
}
int area()
{
cout<< “area of the rectangle="<<(X*Y);
}
}; //End of class
int main()
{
CRectangle R1; // Object creation
R1.set_values(44,22);//call to set_values function
R1.area(); // call to area function
getch();
return 0;
}

